#!/usr/bin/env python3
"""Pill by Pill v6.0h Patch: Origin Stories Batch 7 (60 -> 75) & v6.0 Browser/Accessibility Test Suite.

1. Appends 15 primary-sourced origin stories (checked 2026-11-21 against PMC & NobelPrize.org)
   to `pipeline/origin_stories.json` (idempotently, deduplicated by uppercase `medicine`):
   CIMETIDINE, AZITHROMYCIN, TAMOXIFEN, FLUOROURACIL, PHENYTOIN, HALOPERIDOL, AZATHIOPRINE,
   EMPAGLIFLOZIN, CLOPIDOGREL, LOSARTAN, CIPROFLOXACIN, CYCLOPHOSPHAMIDE, ALBUTEROL,
   FUROSEMIDE, TENOFOVIR DISOPROXIL FUMARATE.
2. Adds `tests/test_v60_site.py` covering all 10 v6.0 interactive routes across desktop (1280px),
   phone (390px, zero horizontal overflow), and dark mode, checking zero console errors, zero
   external network requests, zero commercial links on Explore pages, and axe-core WCAG 2.2 AA.

Usage:
  python3 2026-11-21_v6.0h_origin_stories_batch7_and_v60_browser_tests_patch.py --selftest
  python3 2026-11-21_v6.0h_origin_stories_batch7_and_v60_browser_tests_patch.py --apply /path/to/unpacked_source
"""
import argparse
import json
import pathlib
import py_compile
import tempfile

BATCH7_ORIGINS = [{'medicine': 'CIMETIDINE', 'category': 'Rational drug design', 'simple': 'In the early 1970s, Sir James Black and his team designed cimetidine by modifying histamine so it would block stomach acid receptors instead of turning them on, becoming the first H2-receptor blocker for ulcers and earning a share of the 1988 Nobel Prize.', 'expert': 'Developed in the early 1970s by Sir James W. Black following his receptor-antagonist discovery framework (after propranolol), cimetidine was a first-in-class histamine H2-receptor antagonist that suppressed gastric acid secretion and earned Black a share of the 1988 Nobel Prize in Physiology or Medicine.', 'sources': [{'label': 'NobelPrize.org — Sir James W. Black Facts (1988)', 'url': 'https://www.nobelprize.org/prizes/medicine/1988/black/facts/'}, {'label': 'McGregor (2010), Br J Pharmacol — PMC2947409', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC2947409/'}], 'checked': '2026-11-21'}, {'medicine': 'AZITHROMYCIN', 'category': 'Semi-synthetic natural product', 'simple': 'In 1980, chemists at Pliva in Croatia inserted a nitrogen atom into the ring of the soil-derived antibiotic erythromycin, creating a 15-membered ring that stayed active longer in the body and became azithromycin.', 'expert': 'Synthesized in 1980 at PLIVA Laboratories in Croatia from erythromycin A via a Beckmann rearrangement, reduction, and reductive methylation, inserting a methyl-substituted nitrogen atom to form a 15-membered azalide lactone ring with improved stability, potency, and half-life over erythromycin.', 'sources': [{'label': 'PMC4644142 — Macrolide Antibiotics', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4644142/'}, {'label': 'PMC9355079 — Single-atom heterocycle editing', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9355079/'}], 'checked': '2026-11-21'}, {'medicine': 'TAMOXIFEN', 'category': 'Repurposed targeted therapy', 'simple': 'Tamoxifen (ICI 46,474) was first created in the 1960s at ICI Pharmaceuticals as a potential morning-after contraceptive, but when it failed in that role, researchers repurposed it into the first targeted hormone therapy for breast cancer.', 'expert': 'Discovered as ICI 46,474 under Dr. Arthur L. Walpole at ICI Pharmaceuticals Division (Alderley Park) as a post-coital anti-estrogen contraceptive in rats, tamoxifen was repurposed after Christie Hospital clinical studies (1971) and launched in the UK in 1973 as the first targeted estrogen-receptor therapy for breast cancer.', 'sources': [{'label': 'Jordan (2021) — 50th Anniversary of ICI 46,474, PMC7780369', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7780369/'}, {'label': 'Jordan (2006), Br J Pharmacol — PMC1760730', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC1760730/'}], 'checked': '2026-11-21'}, {'medicine': 'FLUOROURACIL', 'category': 'Rational antimetabolite', 'simple': 'In 1957, Charles Heidelberger and colleagues noticed that rat tumors took up uracil faster than normal tissue, so they swapped one hydrogen atom on uracil for a fluorine atom to create 5-fluorouracil, which jams DNA synthesis in dividing cancer cells.', 'expert': 'Introduced by Charles Heidelberger et al. in 1957 (Nature 179:663–666) as a fluorinated pyrimidine antimetabolite of the uracil anabolic pathway; 5-fluorouracil blocks thymidylate synthase (TS), preventing conversion of deoxyuridylic acid to thymidylic acid and halting DNA synthesis.', 'sources': [{'label': 'PMC6331168 — 5-Fluorouracil background', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6331168/'}, {'label': 'PMC3878070 — XIII International Charles Heidelberger Symposium', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC3878070/'}], 'checked': '2026-11-21'}, {'medicine': 'PHENYTOIN', 'category': 'Phenotypic screening', 'simple': 'German chemist Heinrich Biltz first made phenytoin in 1908, and thirty years later Tracy Putnam and H. Houston Merritt used an electroshock seizure model to show in 1938 that it controlled epilepsy without heavy sedation.', 'expert': 'First synthesized in 1908 by Heinrich Biltz as 5,5-diphenylhydantoin, phenytoin was identified through electroshock convulsion suppression screening and demonstrated for clinical efficacy in epilepsy by H. Houston Merritt and Tracy Putnam in 1938.', 'sources': [{'label': 'PMC6293064 — Brief history of anti-seizure drug development', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6293064/'}, {'label': 'PMC9791846 — Phenytoin review background', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9791846/'}], 'checked': '2026-11-21'}, {'medicine': 'HALOPERIDOL', 'category': 'Medicinal chemistry', 'simple': 'Belgian physician-chemist Paul Janssen synthesized haloperidol in 1958 while searching for stronger painkillers, uncovering the first butyrophenone antipsychotic medicine.', 'expert': 'Synthesized in 1958 at Janssen Laboratories in Belgium by Dr. Paul Janssen, haloperidol became the prototype butyrophenone first-generation antipsychotic.', 'sources': [{'label': 'PMC2802385 — The story of antipsychotics: Past and present', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC2802385/'}, {'label': 'PMC6820922 — Haloperidol background', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6820922/'}], 'checked': '2026-11-21'}, {'medicine': 'AZATHIOPRINE', 'category': 'Rational drug design', 'simple': 'In 1957, Gertrude Elion and George Hitchings designed azathioprine as a slow-release form of 6-mercaptopurine, giving transplant surgeons an immune-suppressing medicine that helped make human kidney transplants possible.', 'expert': 'Developed in 1957 by Gertrude B. Elion and George H. Hitchings (1988 Nobel Prize in Physiology or Medicine) as a thiopurine prodrug converted in vivo to 6-mercaptopurine, azathioprine enabled early prolonged human kidney allograft survival and acts in part through its 6-ThioGTP metabolite on CD28/Rac1 signaling.', 'sources': [{'label': 'NobelPrize.org — 1988 Award Ceremony Speech', 'url': 'https://www.nobelprize.org/prizes/medicine/1988/ceremony-speech/'}, {'label': 'PMC152947 — Azathioprine: old drug, new actions', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC152947/'}, {'label': 'PMC10892228 — Azathioprine and 6-Mercaptopurine review', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10892228/'}], 'checked': '2026-11-21'}, {'medicine': 'EMPAGLIFLOZIN', 'category': 'Natural-product-inspired synthetic', 'simple': 'The story of empagliflozin began in 1835 when French chemists isolated phlorizin from apple tree bark and later found it made kidneys excrete sugar—inspiring modern synthetic SGLT2 inhibitors for diabetes, heart failure, and kidney disease.', 'expert': 'Empagliflozin belongs to the synthetic SGLT2 inhibitor class inspired by phlorizin, a natural glycoside isolated from apple tree root bark in 1835 by French chemists that was later shown to block renal glucose reabsorption via proximal-tubule SGLT2 cotransporters.', 'sources': [{'label': 'PMC12217734 — SGLT2 inhibitors history and populations', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC12217734/'}, {'label': 'PMC10006698 — SGLT2 Inhibitors and CKD', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10006698/'}], 'checked': '2026-11-21'}, {'medicine': 'CLOPIDOGREL', 'category': 'Phenotypic screening', 'simple': 'Clopidogrel and its predecessor ticlopidine were discovered by testing compounds directly in animals before scientists even knew their exact platelet target—later revealed to be the P2Y12 receptor.', 'expert': 'Clopidogrel, a thienopyridine prodrug requiring hepatic bioactivation, was discovered via in vivo phenotypic screening as a structural successor to ticlopidine, with its widespread clinical adoption preceding full characterization of its irreversible P2Y12 receptor antagonism.', 'sources': [{'label': 'PMC1760725 — Antiplatelet drugs', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC1760725/'}, {'label': 'PMC3572712 — Cyclooxygenase Inhibition and P2Y12 Antagonism', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC3572712/'}, {'label': 'PMC10683860 — Antiplatelet strategies: Past, present & future', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10683860/'}], 'checked': '2026-11-21'}, {'medicine': 'LOSARTAN', 'category': 'Structure-guided design', 'simple': "Scientists at DuPont modeled how the blood-pressure hormone angiotensin II fits its receptor and redesigned early weak blockers into losartan, the first oral 'sartan' blood pressure medicine.", 'expert': 'Developed by scientists at DuPont from the hypothesis that lead compounds S-8307 and S-8308 mimicked the C-terminal conformation of angiotensin II at its receptor, losartan became the first approved angiotensin II receptor blocker (ARB) and is oxidized in vivo to the more potent carboxylic acid metabolite EXP3174.', 'sources': [{'label': 'PMC8229937 — Structure-Activity Relationships of Angiotensin II Antagonists', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8229937/'}, {'label': 'PMC11206936 — Repositioning Cardiovascular Agents (background)', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11206936/'}], 'checked': '2026-11-21'}, {'medicine': 'CIPROFLOXACIN', 'category': 'Synthetic antibiotic', 'simple': 'Unlike antibiotics from mold or soil bacteria, ciprofloxacin is completely synthetic—tracing back to nalidixic acid, an accidental 1962 byproduct of making the malaria drug chloroquine.', 'expert': 'Ciprofloxacin is a synthetic fluoroquinolone topoisomerase inhibitor whose class originated from nalidixic acid, discovered by Lesher et al. in 1962 as a byproduct of chloroquine antimalarial synthesis; adding fluorine and piperazine substituents broadened Gram-negative and systemic activity.', 'sources': [{'label': 'PMC7730664 — Quinolones: Mechanism and Contributions', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7730664/'}, {'label': 'PMC12196406 — The Rise, Fall, and Rethink of (Fluoro)quinolones', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC12196406/'}, {'label': 'PMC6836748 — Quinolone antibiotics', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6836748/'}], 'checked': '2026-11-21'}, {'medicine': 'CYCLOPHOSPHAMIDE', 'category': 'Prodrug design', 'simple': "After World War II doctors noticed that mustard gas shrank white blood cells, chemists designed cyclophosphamide as a tamer, inactive 'masked' nitrogen mustard that turns on inside the body to cross-link cancer DNA.", 'expert': 'Evolving from the 1940s discovery of nitrogen mustard alkylating agents for lymphoma (originally traced to bis(2-chloroethyl) sulfide), cyclophosphamide was developed as a metabolically activated nitrogen mustard prodrug with lower direct toxicity than earlier alkylators while retaining DNA guanine N7 cross-linking.', 'sources': [{'label': 'PMC6304445 — Therapeutic Potential of Nitrogen Mustard Based Hybrid Molecules', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6304445/'}, {'label': 'PMC8204947 — Early Effects of Cyclophosphamide, Methotrexate, and 5-Fluorouracil', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8204947/'}], 'checked': '2026-11-21'}, {'medicine': 'ALBUTEROL', 'category': 'Selective receptor design', 'simple': 'In the late 1960s, Sir David Jack and his team created albuterol (called salbutamol outside the US) to open tight asthma airways selectively without making the heart race like older adrenaline-like inhalers.', 'expert': "Developed by Glaxo's research team led by Sir David Jack and Roy Brittain and reported by Cullum, Farmer, Jack, and Levy (Br J Pharmacol, 1969), albuterol (salbutamol) was engineered as a selective beta-2 adrenoceptor agonist for bronchodilation in asthma.", 'sources': [{'label': 'Page (2013), Br J Clin Pharmacol — Sir David Jack, PMC3635591', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC3635591/'}, {'label': 'PMC12499927 — Biased Agonism and Allosteric Modulation (background)', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC12499927/'}], 'checked': '2026-11-21'}, {'medicine': 'FUROSEMIDE', 'category': 'Medicinal chemistry', 'simple': "Discovered in the 1960s after earlier mercury and thiazide water pills, furosemide became the workhorse 'loop diuretic' that quickly clears excess fluid in heart failure.", 'expert': 'Discovered in the 1960s following acetazolamide, spironolactone, and thiazide diuretics of the 1950s, furosemide (4-chloro-N-(2-furyl-methyl)-5-sulfamoyl anthranilic acid, Lasix) introduced potent loop diuresis and has remained a cornerstone for venous congestion in heart failure.', 'sources': [{'label': 'PMC10924023 — Diuretic Treatment in Patients with Heart Failure', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10924023/'}], 'checked': '2026-11-21'}, {'medicine': 'TENOFOVIR DISOPROXIL FUMARATE', 'category': 'Antiviral prodrug', 'simple': 'Building on acyclic nucleotide chemistry pioneered by Antonín Holý and Erik De Clercq, scientists turned tenofovir (first described in 1993) into an oral pill form—tenofovir disoproxil fumarate—that became a pillar of HIV and hepatitis B care.', 'expert': 'Tenofovir ((R)-PMPA), an acyclic nucleoside phosphonate first described in 1993 from the Antonín Holý and Erik De Clercq antiviral collaboration, was formulated as its orally bioavailable disoproxil fumarate prodrug (TDF, Viread) by Gilead for HIV and chronic hepatitis B therapy.', 'sources': [{'label': 'De Clercq (2022) — Honorary Tribute to Antonín Holý, PMC9503179', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9503179/'}, {'label': 'PMC4521268 — Tenofovir Disoproxil Fumarate for Hepatitis B', 'url': 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4521268/'}], 'checked': '2026-11-21'}]
TEST_V60_SITE_PY = '#!/usr/bin/env python3\n"""Browser & WCAG 2.2 AA Accessibility Test Suite for Pill by Pill v6.0 routes.\n\nStarts a local HTTP server over `site/` and verifies all v6.0 interactive routes and static\nSEO landing pages in headless Chromium (via Playwright if installed, skipping gracefully with\nexit 0 if Chromium/Playwright is unavailable in an offline VM):\n  - Desktop (1280x900) and phone (390x844, asserting zero horizontal overflow)\n  - Light mode and Dark mode\n  - Zero console errors and zero uncaught page errors\n  - Zero external network requests\n  - Zero commercial marketplace links (EquipNet, LabX, Federal Equipment, Surplus Solutions)\n    on Explore / student pages (`#/explore/how-drugs-are-built`, `#/explore/departments/...`)\n  - Optional axe-core WCAG 2.2 AA audit when `tests/vendor/axe.min.js` is present.\n\nUsage:\n  python3 tests/test_v60_site.py\n"""\nimport functools\nimport http.server\nimport pathlib\nimport socketserver\nimport sys\nimport threading\n\nROOT = pathlib.Path(__file__).resolve().parent.parent\nSITE_DIR = ROOT / "site"\nAXE_JS = ROOT / "tests" / "vendor" / "axe.min.js"\n\nV60_ROUTES = [\n    "/#/explore/how-drugs-are-built",\n    "/#/explore/departments/formulation",\n    "/#/ref/departments",\n    "/#/ref/departments/analytical",\n    "/#/ref/routes",\n    "/#/ref/equipment",\n    "/#/ref/equipment?view=oems",\n    "/#/ref/equipment?view=kits",\n    "/#/ref/vendors",\n    "/#/ref/vendors?view=parents",\n]\n\nCOMMERCIAL_HOSTS = ("equipnet.com", "labx.com", "fedequip.com", "ssllc.com")\n\n\ndef _start_server(directory: pathlib.Path):\n    handler = functools.partial(http.server.SimpleHTTPRequestHandler, directory=str(directory))\n    class QuietHandler(handler):\n        def log_message(self, *args, **kwargs):\n            pass\n    httpd = socketserver.TCPServer(("127.0.0.1", 0), QuietHandler)\n    port = httpd.server_address[1]\n    t = threading.Thread(target=httpd.serve_forever, daemon=True)\n    t.start()\n    return httpd, port\n\n\ndef run_browser_checks() -> int:\n    try:\n        from playwright.sync_api import sync_playwright\n    except ImportError:\n        print("SKIP: playwright not installed in this environment; run in Chromium-enabled sandbox.")\n        return 0\n\n    httpd, port = _start_server(SITE_DIR)\n    base = f"http://127.0.0.1:{port}"\n    failures = []\n    axe_src = AXE_JS.read_text(encoding="utf-8") if AXE_JS.is_file() else None\n\n    try:\n        with sync_playwright() as p:\n            browser = p.chromium.launch(headless=True)\n            for label, vp, dark in [\n                ("desktop-light", {"width": 1280, "height": 900}, False),\n                ("phone-light", {"width": 390, "height": 844}, False),\n                ("desktop-dark", {"width": 1280, "height": 900}, True),\n            ]:\n                ctx = browser.new_context(viewport=vp, color_scheme="dark" if dark else "light")\n                page = ctx.new_page()\n                console_errs = []\n                ext_reqs = []\n                page.on("console", lambda m: console_errs.append(m.text) if m.type == "error" else None)\n                page.on("pageerror", lambda e: console_errs.append(str(e)))\n                page.on("request", lambda r: ext_reqs.append(r.url) if not r.url.startswith(base) and not r.url.startswith("data:") else None)\n\n                for route in V60_ROUTES:\n                    console_errs.clear()\n                    ext_reqs.clear()\n                    page.goto(base + route, wait_until="networkidle")\n                    page.wait_for_timeout(150)\n\n                    if console_errs:\n                        failures.append(f"{label} {route}: console/page errors: {console_errs}")\n                    if ext_reqs:\n                        failures.append(f"{label} {route}: external requests: {ext_reqs}")\n\n                    if vp["width"] <= 400:\n                        overflow = page.evaluate("() => document.documentElement.scrollWidth > window.innerWidth + 1")\n                        if overflow:\n                            failures.append(f"{label} {route}: horizontal overflow detected at {vp[\'width\']}px")\n\n                    if route.startswith("/#/explore/"):\n                        hrefs = page.evaluate("() => Array.from(document.querySelectorAll(\'a[href]\')).map(a => a.href)")\n                        bad = [h for h in hrefs if any(c in h.lower() for c in COMMERCIAL_HOSTS)]\n                        if bad:\n                            failures.append(f"{label} {route}: commercial link leaked on Explore page: {bad}")\n\n                    if axe_src:\n                        page.add_script_tag(content=axe_src)\n                        viols = page.evaluate("async () => (await axe.run()).violations")\n                        if viols:\n                            ids = [v.get("id") for v in viols]\n                            failures.append(f"{label} {route}: axe-core violations: {ids}")\n\n                ctx.close()\n            browser.close()\n    finally:\n        httpd.shutdown()\n\n    if failures:\n        for f in failures:\n            print("FAIL:", f, file=sys.stderr)\n        return 1\n    print(f"V60_SITE_BROWSER_TESTS_PASSED ({len(V60_ROUTES)} routes x 3 viewports/themes)")\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(run_browser_checks())\n'


def _patch_origin_stories(path: pathlib.Path) -> int:
    if not path.is_file():
        return 0
    doc = json.loads(path.read_text(encoding="utf-8"))
    stories = doc.get("stories") if isinstance(doc, dict) else doc
    if not isinstance(stories, list):
        raise ValueError(f"Unexpected origin_stories.json structure in {path}")
    existing = {str(s.get("medicine", "")).strip().upper() for s in stories}
    added = 0
    for entry in BATCH7_ORIGINS:
        key = entry["medicine"].strip().upper()
        if key not in existing:
            stories.append(entry)
            existing.add(key)
            added += 1
    if added:
        if isinstance(doc, dict):
            doc["stories"] = stories
            path.write_text(json.dumps(doc, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        else:
            path.write_text(json.dumps(stories, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    return added


def apply_patch(root: pathlib.Path) -> dict:
    stories_added = _patch_origin_stories(root / "pipeline" / "origin_stories.json")
    tests_dir = root / "tests"
    tests_dir.mkdir(parents=True, exist_ok=True)
    fp = tests_dir / "test_v60_site.py"
    test_written = (not fp.is_file()) or (fp.read_text(encoding="utf-8") != TEST_V60_SITE_PY)
    if test_written:
        fp.write_text(TEST_V60_SITE_PY, encoding="utf-8")
    return {
        "batch7_origin_stories_added": stories_added,
        "test_v60_site_written": test_written,
    }


def selftest() -> None:
    with tempfile.TemporaryDirectory() as td:
        root = pathlib.Path(td)
        (root / "pipeline").mkdir()
        (root / "tests").mkdir()
        seed = {"stories": [{"medicine": f"DRUG_{i}", "category": "Test", "simple": "a", "expert": "b", "sources": [{"label": "s", "url": "https://example.org"}], "checked": "2026-11-20"} for i in range(60)]}
        (root / "pipeline" / "origin_stories.json").write_text(json.dumps(seed), encoding="utf-8")

        r1 = apply_patch(root)
        assert r1["batch7_origin_stories_added"] == 15 and r1["test_v60_site_written"], r1
        r2 = apply_patch(root)
        assert r2["batch7_origin_stories_added"] == 0 and not r2["test_v60_site_written"], r2

        doc = json.loads((root / "pipeline" / "origin_stories.json").read_text(encoding="utf-8"))
        assert len(doc["stories"]) == 75, len(doc["stories"])
        for s in doc["stories"][-15:]:
            assert s["checked"] == "2026-11-21"
            assert s["sources"] and all(src["url"].startswith("https://") for src in s["sources"])

        py_compile.compile(str(root / "tests" / "test_v60_site.py"), doraise=True)
        print("V60H_BATCH7_ORIGINS_AND_BROWSER_TESTS_SELFTEST_PASSED", json.dumps({"total_stories": len(doc["stories"]), **r1}, indent=2))


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description="Apply Pill by Pill v6.0h Batch 7 Origin Stories & v6.0 Browser Tests patch.")
    ap.add_argument("--apply", type=pathlib.Path, help="Path to unpacked source directory")
    ap.add_argument("--selftest", action="store_true", help="Run built-in verification tests")
    args = ap.parse_args(argv)
    if args.selftest:
        selftest()
        return 0
    if args.apply:
        print(json.dumps(apply_patch(args.apply), indent=2))
        return 0
    ap.error("Provide --apply <dir> or --selftest")
    return 2


if __name__ == "__main__":
    raise SystemExit(main())
